import { test, expect } from '@playwright/test';

test.describe('Assign Category to Record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should display category dropdown on record page', async ({ page }) => {
    // Navigate to a record that needs category assignment
    await page.getByRole('button', { name: /create record/i }).click();
    await page.waitForLoadState('networkidle');

    // Verify the category dropdown is visible
    const categoryDropdown = page.getByLabel(/category/i);
    await expect(categoryDropdown).toBeVisible();
  });

  test('should assign a category from dropdown to a record', async ({ page }) => {
    // Navigate to record creation or edit page
    await page.getByRole('button', { name: /create record/i }).click();
    await page.waitForLoadState('networkidle');

    // Fill in record details
    await page.getByLabel(/record name/i).fill('Test Record');

    // Click on category dropdown
    const categoryDropdown = page.getByLabel(/category/i);
    await categoryDropdown.click();

    // Select a category from the dropdown options
    await page.getByRole('option', { name: /business/i }).click();

    // Verify the category was selected
    await expect(categoryDropdown).toHaveValue('business');

    // Save the record
    await page.getByRole('button', { name: /save/i }).click();

    // Verify success message or navigation
    await expect(page.getByText(/record saved successfully/i)).toBeVisible();
  });

  test('should update category for existing record', async ({ page }) => {
    // Navigate to existing record
    await page.getByRole('link', { name: /test record/i }).click();
    await page.waitForLoadState('networkidle');

    // Click on category dropdown
    const categoryDropdown = page.getByLabel(/category/i);
    await categoryDropdown.click();

    // Select a different category
    await page.getByRole('option', { name: /personal/i }).click();

    // Verify the new category is selected
    await expect(categoryDropdown).toHaveValue('personal');

    // Save changes
    await page.getByRole('button', { name: /save/i }).click();

    // Verify update confirmation
    await expect(page.getByText(/updated successfully/i)).toBeVisible();
  });

  test('should display all available categories in dropdown', async ({ page }) => {
    // Navigate to record page
    await page.getByRole('button', { name: /create record/i }).click();
    await page.waitForLoadState('networkidle');

    // Click on category dropdown to open it
    const categoryDropdown = page.getByLabel(/category/i);
    await categoryDropdown.click();

    // Verify multiple category options are visible
    const businessOption = page.getByRole('option', { name: /business/i });
    const personalOption = page.getByRole('option', { name: /personal/i });
    const workOption = page.getByRole('option', { name: /work/i });

    await expect(businessOption).toBeVisible();
    await expect(personalOption).toBeVisible();
    await expect(workOption).toBeVisible();
  });
});
